C('w2d2-29', 'Фарқ ҷуфт аст?', 'Ду адад a ва b. Агар фарқи онҳо ҷуфт бошад YES, вагарна NO.', ['a', 'b'], '(a - b) % 2 == 0', '(a - b) % 2 == 0', 'YES', 'NO', 'Як сатр: a, b (|x| ≤ 10⁹).',
  ['7 3', '7 4', '-5 1', '0 -1'], lambda r: rn(r, 2, -10**9, 10**9))
P('w2d2-30', 'Рақами калон ҷуфт?', 'Адади дурақамаи n. Агар рақами калонтарини он ҷуфт бошад YES, вагарна NO.', 'Як адад n (10 ≤ n ≤ 99).', 'YES ё NO.',
  body(['n']) + 'long long a = n / 10, b = n % 10;\nlong long m = a;\nif (b > a) m = b;\nif (m % 2 == 0) {\n    cout << "YES" << endl;\n} else {\n    cout << "NO" << endl;\n}',
  lambda s: yn(max(ab(s)[0] // 10, ab(s)[0] % 10) % 2 == 0), ['38', '73', '55', '10'], lambda r: str(R(r, 10, 99)), why=lambda s: f'Рақами калонтарин: {max(s.strip())}.')

