  body(['h']) + 'if (h >= 5 && h <= 11) {\n    cout << "MORNING" << endl;\n} else if (h >= 12 && h <= 16) {\n    cout << "DAY" << endl;\n} else if (h >= 17 && h <= 21) {\n    cout << "EVENING" << endl;\n} else {\n    cout << "NIGHT" << endl;\n}',
