P('w2d3-21', 'Андози даромад', 'Даромад x. То 1000 андоз нест. Аз 1001 то 5000 — 10% аз қисми болои 1000. Аз 5000 зиёд — 400 + 20% аз қисми болои 5000. Андозро чоп кунед (қисми бутун).', 'Як адад x (0 ≤ x ≤ 10⁹).', 'Як адад.',
  body(['x']) + 'if (x <= 1000) {\n    cout << 0 << endl;\n} else if (x <= 5000) {\n    cout << (x - 1000) * 10 / 100 << endl;\n} else {\n    cout << 400 + (x - 5000) * 20 / 100 << endl;\n}',
  lambda s: (lambda x: str(0 if x <= 1000 else (x - 1000) * 10 // 100 if x <= 5000 else 400 + (x - 5000) * 20 // 100))(ab(s)[0]), ['800', '3000', '5000', '10000'], lambda r: str(R(r, 0, 20000)),
  why=lambda s: 'Андоз зина ба зина.')
