# ───────── Рӯзи 5: масъалаҳои мураккаб ─────────
use(2, 5); lvl('Миёна')
P('w2d5-11', 'Ҷамъи ду калонтарин', 'Се адад a, b, c. Ҷамъи ду адади калонтаринро ёбед.', 'Як сатр: a, b, c (|x| ≤ 10⁹).', 'Як адад.',
  body(['a', 'b', 'c']) + 'long long mn = a;\nif (b < mn) mn = b;\nif (c < mn) mn = c;\ncout << a + b + c - mn << endl;', lambda s: str(sum(ab(s)) - min(ab(s))),
  ['1 2 3', '5 5 5', '-1 -2 -3'], lambda r: rn(r, 3, -10**9, 10**9), why=lambda s: 'Ҷамъ − хурдтарин.')
P('w2d5-12', 'Ду адади хурдтарин', 'Се адад a, b, c. Ду адади хурдтаринро бо тартиби афзоиш чоп кунед.', 'Як сатр: a, b, c (|x| ≤ 10⁹).', 'Ду адад.',
  body(['a', 'b', 'c']) + 'if (a > b) { long long t = a; a = b; b = t; }\nif (b > c) { long long t = b; b = c; c = t; }\nif (a > b) { long long t = a; a = b; b = t; }\ncout << a << " " << b << endl;',
  lambda s: ' '.join(map(str, sorted(ab(s))[:2])), ['3 1 2', '5 5 1', '-1 -2 -3'], lambda r: rn(r, 3, -10**9, 10**9), why=lambda s: 'Ададҳоро ба тартиб гузоред.')
P('w2d5-13', 'Наздиктарин ба k', 'Се адад a, b, c ва адади k. Ададеро, ки ба k наздиктар аст, чоп кунед. Агар баробар наздик бошанд, хурдтаринашро.', 'Як сатр: a, b, c, k (|x| ≤ 10⁹).', 'Як адад.',
  body(['a', 'b', 'c', 'k']) + 'long long best = a;\nlong long d = a > k ? a - k : k - a;\nlong long x[2] = {b, c};\nfor (int i = 0; i < 2; i++) {\n    long long e = x[i] > k ? x[i] - k : k - x[i];\n    if (e < d || (e == d && x[i] < best)) {\n        best = x[i];\n        d = e;\n    }\n}\ncout << best << endl;',
  lambda s: (lambda a, b, c, k: str(min([a, b, c], key=lambda x: (abs(x - k), x))))(*ab(s)), ['1 5 9 6', '4 8 2 6', '10 10 10 3'], lambda r: rn(r, 4, -10, 10), why=lambda s: 'Фарқи ҳар адад бо k.')
P('w2d5-14', 'Периметри секунҷа ё NO', 'Се тараф a, b, c. Агар секунҷа сохтан мумкин бошад, периметрро чоп кунед, вагарна NO.', 'Як сатр: a, b, c (1 ≤ x ≤ 10⁹).', 'Адад ё NO.',
  body(['a', 'b', 'c']) + 'if (a + b > c && a + c > b && b + c > a) {\n    cout << a + b + c << endl;\n} else {\n    cout << "NO" << endl;\n}',
  lambda s: (lambda a, b, c: str(a + b + c) if a + b > c and a + c > b and b + c > a else 'NO')(*ab(s)), ['3 4 5', '1 2 3', '2 2 3'], lambda r: rn(r, 3, 1, 10), why=lambda s: 'Ҳар тараф аз ҷамъи дуи дигар хурд бошад.')
C('w2d5-15', 'Буррандаҳо мебуранд?', 'Ду бурранда дар хат: [a; b] ва [c; d] (a ≤ b, c ≤ d). Агар нуқтаи умумӣ дошта бошанд YES, вагарна NO.', ['a', 'b', 'c', 'd'], '(a > c ? a : c) <= (b < d ? b : d)', 'max(a, c) <= min(b, d)',
  'YES', 'NO', 'Як сатр: a, b, c, d (|x| ≤ 10⁹).', ['1 5 3 8', '1 2 3 4', '1 3 3 5'], lambda r: (lambda a, c: f'{a} {R(r, a, 20)} {c} {R(r, c, 20)}')(R(r, 0, 20), R(r, 0, 20)))
P('w2d5-16', 'Дарозии қисми умумӣ', 'Ду бурранда [a; b] ва [c; d] (a ≤ b, c ≤ d). Дарозии қисми умумии онҳоро ёбед (агар набошад — 0).', 'Як сатр: a, b, c, d (|x| ≤ 10⁹).', 'Як адад.',
  body(['a', 'b', 'c', 'd']) + 'long long l = a > c ? a : c;\nlong long r = b < d ? b : d;\nif (r > l) {\n    cout << r - l << endl;\n} else {\n    cout << 0 << endl;\n}',
  lambda s: (lambda a, b, c, d: str(max(0, min(b, d) - max(a, c))))(*ab(s)), ['1 5 3 8', '1 2 3 4', '0 10 2 3'], lambda r: (lambda a, c: f'{a} {R(r, a, 30)} {c} {R(r, c, 30)}')(R(r, 0, 20), R(r, 0, 20)),
  why=lambda s: 'min(охирҳо) − max(аввалҳо).')
P('w2d5-17', 'Се адад камшаванда', 'Се адад a, b, c. Онҳоро аз калон ба хурд чоп кунед.', 'Як сатр: a, b, c (|x| ≤ 10⁹).', 'Се адад.',
  body(['a', 'b', 'c']) + 'if (a < b) { long long t = a; a = b; b = t; }\nif (b < c) { long long t = b; b = c; c = t; }\nif (a < b) { long long t = a; a = b; b = t; }\ncout << a << " " << b << " " << c << endl;',
  lambda s: ' '.join(map(str, sorted(ab(s), reverse=True))), ['1 3 2', '5 5 1', '-3 0 3'], lambda r: rn(r, 3, -10**9, 10**9), why=lambda s: 'Аз калон ба хурд.')
P('w2d5-18', 'Масоҳати калонтар', 'Ду росткунҷа: a × b ва c × d. Масоҳати калонтарро ва рақами росткунҷаро (1 ё 2; агар баробар — 0) чоп кунед.', 'Як сатр: a, b, c, d (1 ≤ x ≤ 10⁹).', 'Ду адад.',
  body(['a', 'b', 'c', 'd']) + 'long long s1 = a * b, s2 = c * d;\nif (s1 > s2) {\n    cout << s1 << " " << 1 << endl;\n} else if (s2 > s1) {\n    cout << s2 << " " << 2 << endl;\n} else {\n    cout << s1 << " " << 0 << endl;\n}',
  lambda s: (lambda a, b, c, d: f'{a * b} 1' if a * b > c * d else f'{c * d} 2' if c * d > a * b else f'{a * b} 0')(*ab(s)), ['3 4 2 5', '2 2 1 5', '2 3 3 2'], lambda r: rn(r, 4, 1, 10),
  why=lambda s: (lambda a, b, c, d: f'{a * b} ва {c * d}')(*ab(s)))
P('w2d5-19', 'Хурдтарин ва рақами он', 'Се ададро ба тартиб хонед. Хурдтаринро ва рақами тартибии онро (1, 2 ё 3; агар чанд бошад — аввалинашро) чоп кунед.', 'Як сатр: a, b, c (|x| ≤ 10⁹).', 'Ду адад.',
  body(['a', 'b', 'c']) + 'long long m = a;\nint p = 1;\nif (b < m) { m = b; p = 2; }\nif (c < m) { m = c; p = 3; }\ncout << m << " " << p << endl;',
  lambda s: (lambda v: f'{min(v)} {v.index(min(v)) + 1}')(ab(s)), ['5 2 7', '3 3 1', '4 4 4'], lambda r: rn(r, 3, -5, 5), why=lambda s: 'Агар баробар бошад, ҷойро иваз намекунем.')
P('w2d5-20', 'Мағозаи арзонтарин', 'Нархи мол дар се мағоза a, b, c. Нархи арзонтарин ва рақами мағозаро (1, 2 ё 3; агар баробар — аввалинашро) чоп кунед.', 'Як сатр: a, b, c (1 ≤ x ≤ 10⁹).', 'Ду адад.',
  body(['a', 'b', 'c']) + 'long long m = a;\nint k = 1;\nif (b < m) { m = b; k = 2; }\nif (c < m) { m = c; k = 3; }\ncout << m << " " << k << endl;',
  lambda s: (lambda v: f'{min(v)} {v.index(min(v)) + 1}')(ab(s)), ['120 95 110', '50 50 60', '9 8 7'], lambda r: rn(r, 3, 1, 20), why=lambda s: 'Арзонтаринро ёбед.')

lvl('Душвор')
P('w2d5-21', 'Рӯзи оянда', 'Сана: рӯз d, моҳ m, сол y. Санаи рӯзи баъдиро чоп кунед (бо назардошти соли кабиса).', 'Як сатр: d, m, y (санаи дуруст, 1 ≤ y ≤ 9999).', 'Се адад: рӯз, моҳ, сол.',
  body(['d', 'm', 'y']) + 'long long days = 31;\nif (m == 4 || m == 6 || m == 9 || m == 11) {\n    days = 30;\n} else if (m == 2) {\n    if ((y % 4 == 0 && y % 100 != 0) || y % 400 == 0) days = 29;\n    else days = 28;\n}\nd++;\nif (d > days) {\n    d = 1;\n    m++;\n    if (m > 12) {\n        m = 1;\n        y++;\n    }\n}\ncout << d << " " << m << " " << y << endl;',
  lambda s: (lambda d, m, y: (lambda days: (f'{d + 1} {m} {y}' if d < days else f'1 {m + 1} {y}' if m < 12 else f'1 1 {y + 1}'))(30 if m in (4, 6, 9, 11) else (29 if (y % 4 == 0 and y % 100 != 0) or y % 400 == 0 else 28) if m == 2 else 31))(*ab(s)),
  ['28 2 2024', '28 2 2023', '31 12 2025', '30 4 2026', '29 2 2000', '28 2 1900', '15 6 2026'], lambda r: (lambda m, y: f'{R(r, 1, 28)} {m} {y}')(R(r, 1, 12), R(r, 1900, 2100)),
  why=lambda s: 'Рӯзҳои моҳ ва соли кабисаро санҷед.')
P('w2d5-22', 'Ду росткунҷа ба ҳам мерасанд?', 'Ду росткунҷа бо тарафҳои параллел ба тирҳо: [x1; x2] × [y1; y2] ва [x3; x4] × [y3; y4]. Агар нуқтаи умумӣ дошта бошанд YES, вагарна NO.', 'Як сатр: x1 x2 y1 y2 x3 x4 y3 y4 (x1 ≤ x2, y1 ≤ y2, x3 ≤ x4, y3 ≤ y4).', 'YES ё NO.',
  body(['a', 'b', 'c', 'd', 'e', 'f', 'g', 'h']) + 'bool ox = (a > e ? a : e) <= (b < f ? b : f);\nbool oy = (c > g ? c : g) <= (d < h ? d : h);\nif (ox && oy) {\n    cout << "YES" << endl;\n} else {\n    cout << "NO" << endl;\n}',
  lambda s: (lambda a, b, c, d, e, f, g, h: yn(max(a, e) <= min(b, f) and max(c, g) <= min(d, h)))(*ab(s)), ['0 4 0 4 2 6 2 6', '0 1 0 1 2 3 2 3', '0 2 0 2 2 4 1 3'],
  lambda r: (lambda a, c, e, g: f'{a} {R(r, a, 10)} {c} {R(r, c, 10)} {e} {R(r, e, 10)} {g} {R(r, g, 10)}')(R(r, 0, 10), R(r, 0, 10), R(r, 0, 10), R(r, 0, 10)),
  why=lambda s: 'Дар ҳарду тир буррандаҳо бояд бурранд.')
P('w2d5-23', 'Прогрессия ҳаст?', 'Се адад a, b, c (бо тартиби дилхоҳ). Агар онҳоро бо ягон тартиб гузошта, прогрессияи арифметикӣ сохтан мумкин бошад YES, вагарна NO.', 'Як сатр: a, b, c (|x| ≤ 10⁹).', 'YES ё NO.',
  body(['a', 'b', 'c']) + 'if (a > b) { long long t = a; a = b; b = t; }\nif (b > c) { long long t = b; b = c; c = t; }\nif (a > b) { long long t = a; a = b; b = t; }\nif (2 * b == a + c) {\n    cout << "YES" << endl;\n} else {\n    cout << "NO" << endl;\n}',
  lambda s: (lambda v: yn(2 * v[1] == v[0] + v[2]))(sorted(ab(s))), ['5 1 3', '1 2 4', '7 7 7', '10 4 7'], lambda r: rn(r, 3, 0, 8), why=lambda s: 'Пас аз тартиб: 2·миёна = хурд + калон.')
P('w2d5-24', 'Решаҳои муодила', 'Муодилаи a·x² + b·x + c = 0 (a ≠ 0). Чанд решаи ҳақиқӣ дорад? (Дискриминант D = b² − 4ac.)', 'Як сатр: a, b, c (|x| ≤ 10⁴, a ≠ 0).', '0, 1 ё 2.',
  body(['a', 'b', 'c']) + 'long long D = b * b - 4 * a * c;\nif (D > 0) {\n    cout << 2 << endl;\n} else if (D == 0) {\n    cout << 1 << endl;\n} else {\n    cout << 0 << endl;\n}',
  lambda s: (lambda a, b, c: '2' if b * b - 4 * a * c > 0 else '1' if b * b - 4 * a * c == 0 else '0')(*ab(s)), ['1 -3 2', '1 2 1', '1 0 1', '2 4 2'],
  lambda r: f'{r.choice([-3, -2, -1, 1, 2, 3])} {R(r, -6, 6)} {R(r, -6, 6)}', why=lambda s: (lambda a, b, c: f'D = {b * b - 4 * a * c}')(*ab(s)))
P('w2d5-25', 'Масофа то бурранда', 'Нуқтаи x ва бурранда [a; b] (a ≤ b). Масофаи кӯтоҳтарин аз x то бурраандаро ёбед (агар дар дохил бошад — 0).', 'Як сатр: x, a, b (|x| ≤ 10⁹).', 'Як адад.',
  body(['x', 'a', 'b']) + 'if (x < a) {\n    cout << a - x << endl;\n} else if (x > b) {\n    cout << x - b << endl;\n} else {\n    cout << 0 << endl;\n}',
  lambda s: (lambda x, a, b: str(a - x if x < a else x - b if x > b else 0))(*ab(s)), ['1 3 7', '5 3 7', '10 3 7'], lambda r: (lambda a: f'{R(r, -20, 20)} {a} {R(r, a, 20)}')(R(r, -20, 20)),
  why=lambda s: 'Чап, дохил ё рост.')
P('w2d5-26', 'Калонтарин ва ҷояш', 'Се адад. Калонтаринро ва рақами тартибии онро (1, 2 ё 3; агар баробар — аввалинашро) чоп кунед.', 'Як сатр: a, b, c (|x| ≤ 10⁹).', 'Ду адад.',
  body(['a', 'b', 'c']) + 'long long m = a;\nint p = 1;\nif (b > m) { m = b; p = 2; }\nif (c > m) { m = c; p = 3; }\ncout << m << " " << p << endl;',
  lambda s: (lambda v: f'{max(v)} {v.index(max(v)) + 1}')(ab(s)), ['5 9 7', '9 9 1', '-1 -2 -3'], lambda r: rn(r, 3, -5, 5), why=lambda s: 'Танҳо калонтари қатъӣ ҷойро иваз мекунад.')
P('w2d5-27', 'Санг, қайчӣ, коғаз', 'Ду бозингар: 1 — санг, 2 — қайчӣ, 3 — коғаз. Санг қайчиро, қайчӣ коғазро, коғаз сангро мебарад. FIRST, SECOND ё DRAW.', 'Як сатр: a, b (1 ≤ x ≤ 3).', 'FIRST, SECOND ё DRAW.',
  body(['a', 'b']) + 'if (a == b) {\n    cout << "DRAW" << endl;\n} else if ((a == 1 && b == 2) || (a == 2 && b == 3) || (a == 3 && b == 1)) {\n    cout << "FIRST" << endl;\n} else {\n    cout << "SECOND" << endl;\n}',
  lambda s: (lambda a, b: 'DRAW' if a == b else 'FIRST' if (a, b) in [(1, 2), (2, 3), (3, 1)] else 'SECOND')(*ab(s)), ['1 2', '1 3', '2 2', '3 1', '2 1', '3 2', '1 1', '2 3', '3 3'],
  why=lambda s: 'Се ҳолати ғалаба барои якум.')
P('w2d5-28', 'Фарқи ду соат', 'Ду вақт h1:m1 ва h2:m2 дар як рӯз. Фарқи байни онҳоро бо дақиқа (ҳамеша мусбат ё 0) ёбед.', 'Як сатр: h1, m1, h2, m2.', 'Як адад.',
  body(['a', 'b', 'c', 'd']) + 'long long x = a * 60 + b, y = c * 60 + d;\nif (x > y) {\n    cout << x - y << endl;\n} else {\n    cout << y - x << endl;\n}',
  lambda s: (lambda a, b, c, d: str(abs(a * 60 + b - c * 60 - d)))(*ab(s)), ['8 30 10 0', '10 0 8 30', '12 0 12 0'], lambda r: f'{R(r, 0, 23)} {R(r, 0, 59)} {R(r, 0, 23)} {R(r, 0, 59)}',
  why=lambda s: 'Ба дақиқа табдил диҳед.')
P('w2d5-29', 'Пардохт бо тангаҳо', 'Нарх p. Шумо a тангаи 5-дирамӣ ва b тангаи 1-дирамӣ доред. Агар нархро айнан (бе бақия) пардохт кардан мумкин бошад YES, вагарна NO.', 'Як сатр: p, a, b (0 ≤ x ≤ 10⁹).', 'YES ё NO.',
  body(['p', 'a', 'b']) + 'long long f = p / 5;\nif (f > a) f = a;\nif (p - f * 5 <= b) {\n    cout << "YES" << endl;\n} else {\n    cout << "NO" << endl;\n}',
  lambda s: (lambda p, a, b: yn(p - min(a, p // 5) * 5 <= b))(*ab(s)), ['13 2 3', '13 1 3', '20 5 0', '7 0 7'], lambda r: rn(r, 3, 0, 20), why=lambda s: 'Аввал ҳарчи бештар 5-дирамӣ.')
P('w2d5-30', 'Нуқта ва доира', 'Доира бо маркази (cx, cy) ва радиуси r. Нуқтаи (x, y) дар дохил (INSIDE), дар хат (ON) ё берун (OUTSIDE) аст?', 'Як сатр: cx, cy, r, x, y (|x| ≤ 10⁴, 0 ≤ r ≤ 10⁴).', 'INSIDE, ON ё OUTSIDE.',
  body(['a', 'b', 'r', 'x', 'y']) + 'long long d = (x - a) * (x - a) + (y - b) * (y - b);\nif (d < r * r) {\n    cout << "INSIDE" << endl;\n} else if (d == r * r) {\n    cout << "ON" << endl;\n} else {\n    cout << "OUTSIDE" << endl;\n}',
  lambda s: (lambda a, b, r, x, y: (lambda d: 'INSIDE' if d < r * r else 'ON' if d == r * r else 'OUTSIDE')((x - a) ** 2 + (y - b) ** 2))(*ab(s)), ['0 0 5 3 4', '0 0 5 1 1', '0 0 5 6 0', '1 1 2 1 1'],
  lambda r: f'{R(r, -5, 5)} {R(r, -5, 5)} {R(r, 0, 6)} {R(r, -8, 8)} {R(r, -8, 8)}', why=lambda s: 'Квадрати масофаро бо r² муқоиса кунед.')

