  body(['a', 'b']) + 'if (a == 0) {\n    if (b == 0) cout << "INF" << endl;\n    else cout << "NO" << endl;\n} else if (b % a == 0) {\n    cout << -b / a << endl;\n} else {\n    cout << "NO" << endl;\n}',
