  lambda s: (lambda a, b, c, d, e, f, g, h: str(max(0, min(b, f) - max(a, e)) * max(0, min(d, h) - max(c, g))))(*ab(s)), ['0 4 0 4 2 6 2 6', '0 1 0 1 2 3 2 3', '0 10 0 10 2 3 2 3'],
